// ---- world ----
// world system — v12, integrated from the deployed v11.

function hashJitter(x, y, z) {
  let h = (x * 73856093) ^ (y * 19349663) ^ (z * 83492791);
  h = Math.abs(h % 100) / 100;
  return 0.92 + h * 0.16;
}

function setBlock(x, y, z, t, hp) {
  blocks.set(key(x, y, z), { t, hp: hp || 0 });
  rebuild();
}

function removeBlock(x, y, z) {
  const k = key(x, y, z),
    b = blocks.get(k);
  if (!b) return;
  blocks.delete(k);
  if (turretObjs.has(k)) {
    disposeObject(turretObjs.get(k));
    turretObjs.delete(k);
  }
  if (flameObjs.has(k)) {
    disposeObject(flameObjs.get(k));
    flameObjs.delete(k);
  }
  if (warehouseObjs.has(k)) {
    disposeObject(warehouseObjs.get(k));
    warehouseObjs.delete(k);
  }
  if (wallDecorObjs.has(k)) {
    disposeObject(wallDecorObjs.get(k));
    wallDecorObjs.delete(k);
  }
  if (defenseLabelEls.has(k)) {
    defenseLabelEls.get(k).remove();
    defenseLabelEls.delete(k);
  }
  const st = defenseState.get(k);
  if (st?.type === "warehouse")
    warehouseBonus = Math.max(0, warehouseBonus - 40 - (st.level - 1) * 25);
  defenseState.delete(k);
  if (st) restoreBuildPad(x, z);
  rebuild();
}

function blockAt(x, y, z) {
  return blocks.get(key(x, y, z));
}

function buildTerrain() {
  buildRegionTerrain();
  terrainSeed=journey?.seed||dailyRun?.seed||((Date.now()>>>0)||1);
  blocks.clear();
  turretObjs.forEach((g) => disposeObject(g));
  turretObjs.clear();
  flameObjs.forEach((g) => disposeObject(g));
  flameObjs.clear();
  warehouseObjs.forEach((g) => disposeObject(g));
  warehouseObjs.clear();
  wallDecorObjs.forEach((g) => disposeObject(g));
  wallDecorObjs.clear();
  defenseLabelEls.forEach((el) => el.remove());
  defenseLabelEls.clear();
  defenseState.clear();
  for (let x = -WORLD_EDGE; x <= WORLD_EDGE; x++)
    for (let z = -WORLD_EDGE; z <= WORLD_EDGE; z++) {
      const r = Math.max(Math.abs(x), Math.abs(z));
      if (r <= R_INNER) blocks.set(key(x, 0, z), { t: "snow", hp: 0 });
      else if (r <= WORLD_EDGE) {
        blocks.set(key(x,0,z),{t:'snow',hp:0});
      }
    }
  let placed = 0,
    guard = 0;
  while (placed < 42 && guard++ < 2200) {
    const x = ((terrainRandom() * 2 - 1) * (23)) | 0,
      z = ((terrainRandom() * 2 - 1) * (23)) | 0;
    if (Math.max(Math.abs(x), Math.abs(z)) < 6 || isReservedBuildArea(x, z) || regionCollision(x,z))
      continue;
    if (Math.abs(x) <= 4 && z >= 2 && z <= 11) continue;
    if (!stageResourceZone("tree", x, z)) continue;
    if([...blocks].some(([k,b])=>{if(b.t!=='wood')return false;const [ox,y,oz]=k.split(',').map(Number);return y===1&&Math.hypot(x-ox,z-oz)<3.2;}))continue;
    let ok = true;
    for (let y = 1; y <= 5; y++)
      if (blockAt(x, y, z)) {
        ok = false;
        break;
      }
    if (!ok) continue;
    for (let y = 1; y <= 3; y++) blocks.set(key(x, y, z), { t: "wood", hp: 0 });
    for (let dx = -1; dx <= 1; dx++)
      for (let dz = -1; dz <= 1; dz++)
        if (!blockAt(x + dx, 4, z + dz))
          blocks.set(key(x + dx, 4, z + dz), { t: "leaf", hp: 0 });
    blocks.set(key(x, 5, z), { t: "leaf", hp: 0 });
    if (
      false &&
      !blockAt(x + 2, 1, z + 1) &&
      !isReservedBuildArea(x + 2, z + 1) &&
      stageResourceZone("tree", x + 2, z + 1)
    ) {
      for (let y = 1; y <= 2; y++)
        blocks.set(key(x + 2, y, z + 1), { t: "wood", hp: 0 });
      if (!blockAt(x + 2, 3, z + 1))
        blocks.set(key(x + 2, 3, z + 1), { t: "leaf", hp: 0 });
    }
    placed++;
  }
  placed = 0;
  guard = 0;
  while (placed < 22 && guard++ < 1400) {
    const x = ((terrainRandom() * 2 - 1) * (23)) | 0,
      z = ((terrainRandom() * 2 - 1) * (23)) | 0;
    if (
      Math.max(Math.abs(x), Math.abs(z)) < 6 ||
      blockAt(x, 1, z) ||
      isReservedBuildArea(x, z) || regionCollision(x,z) ||
      !stageResourceZone("coal", x, z)
    )
      continue;
    blocks.set(key(x, 1, z), { t: "coal", hp: 0 });
    if (terrainRandom() < 0.75 && !blockAt(x, 2, z))
      blocks.set(key(x, 2, z), { t: "coal", hp: 0 });
    if (terrainRandom() < .35 && !blockAt(x + 1, 1, z) && !isReservedBuildArea(x + 1,z) && !regionCollision(x+1,z))
      blocks.set(key(x + 1, 1, z), { t: "coal", hp: 0 });
    placed++;
  }
  rebuild();
}

function flushWorld() {
  updateCanopyFocus();
  if (!worldDirty) return;
  worldDirty = false;
  const m = new THREE.Matrix4(),
    c = new THREE.Color();
  let count = 0,
    spare = inst.instanceMatrix.count - blockArr.length;
  for (const e of blockArr) {
    const parts = resourceVisualParts(e);
    if (parts && spare >= parts.length - 1) {
      spare -= parts.length - 1;
      // Low young spruce around the working camp; the distant forest keeps its height.
      // Only render transforms change. Resource cells and yields stay identical.
      const youngTree=(e.b.t==='wood'||e.b.t==='leaf') && Math.max(Math.abs(e.x),Math.abs(e.z))<16 && !(e.x===-4&&e.z===4);
      const scale=youngTree?(.64+((Math.abs(e.x*13+e.z*7)%5)*.045)):1;
      const biome=journey&&(e.b.t==='wood'||e.b.t==='leaf')?journeyConfig().biome:-1;
      const sx=scale*(biome===0?1.08:biome===1?.64:biome===2?.88:1),sy=scale*(biome===0?1.2:biome===1?.9:biome===2?.52:1);
      for (const [dx, dy, dz, w, h, d, color] of parts) {
        m.makeScale(w*sx, h*sy, d*sx);
        m.setPosition(e.x + dx*sx, .5+(e.y+dy-.5)*sy, e.z + dz*sx);
        inst.setMatrixAt(count, m);
        c.setHex(color).multiplyScalar(hashJitter(e.x, e.y, e.z));
        inst.geometry.attributes.canopy.setX(count, e.b.t === "leaf" ? 1 : 0);
          inst.geometry.attributes.canopyAnchor.setXYZ(count,e.x,.5+(e.y-.5)*sy,e.z);
        inst.setColorAt(count++, c);
      }
    } else {
      inst.geometry.attributes.canopy.setX(count,0);
        m.makeTranslation(e.x, e.y, e.z);
      inst.setMatrixAt(count, m);
      c.setHex(stageBlockColor(e)).multiplyScalar(e.b.t==='snow'?1:hashJitter(e.x, e.y, e.z));
      inst.setColorAt(count++, c);
    }
  }
  inst.geometry.attributes.canopy.needsUpdate = true;
  inst.geometry.attributes.canopyAnchor.needsUpdate = true;
  inst.count = count;
  inst.instanceMatrix.needsUpdate = true;
  if (inst.instanceColor) inst.instanceColor.needsUpdate = true;
  inst.computeBoundingSphere();
}
function rebuild() {
  worldDirty = true;
  blockArr = [...blocks.entries()].map(([k, b]) => {
    const [x, y, z] = k.split(",").map(Number);
    return { x, y, z, b };
  });
}

