function makeRing(radius, color, opacity) {
  const g = new THREE.RingGeometry(radius - 0.08, radius, 40),
    m = new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity,
      side: THREE.DoubleSide,
      depthWrite: false,
    }),
    mesh = new THREE.Mesh(g, m);
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.y = 0.56;
  return mesh;
}

function box(w, h, d, color) {
  return new THREE.Mesh(
    new THREE.BoxGeometry(w, h, d),
    new THREE.MeshLambertMaterial({ color }),
  );
}

function vbox(w, h, d, color, px = 0, py = 0, pz = 0) {
  const m = box(w, h, d, color);
  m.position.set(px, py, pz);
  return m;
}

function addVoxelDetails(g, defs) {
  for (const d of defs) {
    const m = vbox(d[0], d[1], d[2], d[3], d[4], d[5], d[6]);
    g.add(m);
  }
}

// Dispose resources owned by a removed model; shared pickup assets are pooled separately.
function disposeObject(object) {
  if (!object) return;
  object.removeFromParent();
  const geometries = new Set(),
    materials = new Set();
  object.traverse((o) => {
    if (o.geometry) geometries.add(o.geometry);
    for (const m of Array.isArray(o.material) ? o.material : [o.material])
      if (m) materials.add(m);
  });
  geometries.forEach((g) => g.dispose());
  materials.forEach((m) => m.dispose());
}

function updateEnvironment(dt, t) {
  nightK += ((phase === "night" ? 1 : 0) - nightK) * Math.min(1, dt * 1.2);
  sun.intensity = 1.9 - nightK * 1.62;
  sun.color.setHex(phase === "night" ? 0x739bd9 : 0xffffff);
  hemi.intensity = 1.75 - nightK * 1.37;
  if(scene.fog)scene.fog.color.setHex(phase==='night'?0x17384e:0xb5d4df);
  const sa = (phase === "day" ? 1 - phaseT / 30 : 0.5) * Math.PI;
  sun.position.set(Math.cos(sa) * 30, Math.max(6, Math.sin(sa) * 30), 10);
  const fr = fuel / 100;
  fireLight.intensity =
    (0.6 + fr * 2.2) * (1 + nightK * 0.8) + Math.sin(t * 11) * 0.25;
  fireLight.distance = 8 + fr * 16;
  if(campGlow)campGlow.material.uniforms.strength.value=(.2+nightK*.36)*fr;
}


// ---- voxel-style ----
// Visual sub-voxels use the existing world instancing draw. Logical resource cells stay intact.
// Reserve one slot per remaining logical block; detail degrades safely if capacity is tight.
const canopyFocus = { value: new THREE.Vector2(-10, -10) },
  canopyTarget = { value: new THREE.Vector2(-10, -10) };
function installCanopyMaterial(mat) {
  mat.onBeforeCompile = shader => {
    shader.uniforms.canopyFocus = canopyFocus;
    shader.uniforms.canopyTarget = canopyTarget;
    shader.vertexShader = 'attribute float canopy; attribute vec3 canopyAnchor; uniform vec2 canopyFocus; uniform vec2 canopyTarget;\n' + shader.vertexShader;
    shader.vertexShader = shader.vertexShader.replace('#include <project_vertex>', `
      vec4 mvPosition = vec4(transformed,1.0);
      #ifdef USE_INSTANCING
        mvPosition = instanceMatrix * mvPosition;
      #endif
      if(canopy > .5){
        vec4 crownScreen=projectionMatrix*modelViewMatrix*vec4(canopyAnchor,1.0);
        vec2 crownUV=crownScreen.xy/crownScreen.w;
        float clearance=min(distance(crownUV,canopyFocus),distance(crownUV,canopyTarget));
        float openness=smoothstep(.17,.34,clearance);
        mvPosition.xyz=mix(canopyAnchor,mvPosition.xyz,mix(.06,1.0,openness));
      }
      mvPosition=modelViewMatrix*mvPosition;
      gl_Position=projectionMatrix*mvPosition;
    `);
  };
}
function updateCanopyFocus() {
  if (!camera || !pPos) return;
  // Result framing celebrates the whole settlement; restore solid foliage.
  if (stageClear || victoryScene) {
    canopyFocus.value.set(-10, -10);
    canopyTarget.value.set(-10, -10);
    return;
  }
  const p = new THREE.Vector3(pPos.x, 1.5, pPos.z).project(camera);
  canopyFocus.value.set(p.x, p.y);
  const target = constructionSites[0]?.p || actionFocus || (introStep >= 2 ? objectiveTarget : null);
  if (target) {
    const q = new THREE.Vector3(target.x, 1, target.z).project(camera);
    canopyTarget.value.set(q.x, q.y);
  } else canopyTarget.value.set(-10, -10);
}
function updateLegacyEdgeCues() {
  $('flankDirection').hidden=true;
  if(introStep<4){$('furnaceDirection').hidden=true;$('raidDirection').hidden=true;return;}
  const rect = renderer.domElement.getBoundingClientRect();
  function place(id, x, z, label, always) {
    const el = $(id), p = new THREE.Vector3(x, 1, z).project(camera);
    const sx = (p.x * .5 + .5) * rect.width, sy = (-p.y * .5 + .5) * rect.height;
    el.hidden = !running || (!always && sx > 28 && sx < rect.width - 28 && sy > 135 && sy < rect.height - 100);
    if (el.hidden) return;
    const dx = sx - rect.width / 2, dy = sy - rect.height / 2;
    const a = Math.atan2(dy, dx), arrows = ['→','↘','↓','↙','←','↖','↑','↗'];
    el.textContent = arrows[(Math.round(a / (Math.PI / 4)) + 8) % 8] + ' ' + label;
    const scale = Math.min((rect.width / 2 - 48) / Math.max(1, Math.abs(dx)), (rect.height / 2 - 145) / Math.max(1, Math.abs(dy)));
    const half=Math.min(rect.width/2-8,el.offsetWidth/2+8);
    el.style.left = Math.max(half,Math.min(rect.width-half,rect.width / 2 + dx * scale)) + 'px';
    el.style.top = rect.height / 2 + dy * scale + 'px';
  }
  place('furnaceDirection', 0, 0, '炉', false);
  if (nextRaid && introStep >= 4) place('raidDirection', Math.cos(nextRaid.angle) * 30, Math.sin(nextRaid.angle) * 30, phase === 'night' ? '襲撃' : '次の襲撃', true);
  else $('raidDirection').hidden = true;
  if(bossFlank?.wait>=0 && running && !paused) {
    const a=(nextRaid?.angle||0)+Math.PI;
    place('flankDirection',Math.cos(a)*30,Math.sin(a)*30,'側面2体・まもなく',true);
  }
}
