const fadedBuildingMeshes=new Set();
function restoreBuildingOcclusion(){
 for(const mesh of fadedBuildingMeshes){const s=mesh.userData.occlusionOriginal;Object.assign(mesh.material,s);mesh.material.needsUpdate=true;delete mesh.userData.occlusionOriginal;}
 fadedBuildingMeshes.clear();
}
function updateBuildingOcclusion(dt){
 const points=[pPos.clone().add(new THREE.Vector3(0,.8,0)),pPos.clone().add(new THREE.Vector3(0,1.9,0))];
 if(phase==='night')points.push(...enemies.filter(enemyTargetable).filter(e=>e.model.g.position.distanceTo(pPos)<playerWeapon().range).sort((a,b)=>a.model.g.position.distanceTo(pPos)-b.model.g.position.distanceTo(pPos)).slice(0,3).map(enemyAimPoint));
 if(survivalEnabled&&phase==='night'&&harvestTool){player.updateMatrixWorld(true);points.push(harvestTool.getWorldPosition(new THREE.Vector3()));}
 const rays=points.map(p=>({ray:new THREE.Ray(camera.position.clone(),p.clone().sub(camera.position).normalize()),distance:p.distanceTo(camera.position)}));
 const obscuring=new Set(),bounds=new THREE.Box3(),hit=new THREE.Vector3();
 for(const g of [fireGroup,...(campCore?[campCore]:[]),...settlementObjs,...turretObjs.values(),...flameObjs.values(),...warehouseObjs.values(),...wallDecorObjs.values()]){
  if(!g.visible||g.position.distanceTo(pPos)>20)continue;
  g.updateMatrixWorld(true);
  g.traverse(m=>{
   if(!m.isMesh||!m.visible||!m.geometry||Array.isArray(m.material))return;
   if(!m.geometry.boundingBox)m.geometry.computeBoundingBox();
   bounds.copy(m.geometry.boundingBox).applyMatrix4(m.matrixWorld);
   if(survivalEnabled)bounds.expandByScalar(.35);
   if(bounds.max.y<1.3)return;
   if(rays.some(r=>r.ray.intersectBox(bounds,hit)&&hit.distanceTo(camera.position)<r.distance-.35))obscuring.add(m);
  });
 }
 for(const m of obscuring){if(!fadedBuildingMeshes.has(m)){m.userData.occlusionOriginal={opacity:m.material.opacity,transparent:m.material.transparent,depthWrite:m.material.depthWrite};fadedBuildingMeshes.add(m);m.material.needsUpdate=true;}}
 for(const m of fadedBuildingMeshes){
  const original=m.userData.occlusionOriginal,target=obscuring.has(m)?.18:original.opacity;
  m.material.transparent=true;m.material.opacity+=(target-m.material.opacity)*Math.min(1,dt*14);m.material.depthWrite=false;
  if(!obscuring.has(m)&&Math.abs(m.material.opacity-original.opacity)<.01){Object.assign(m.material,original);m.material.needsUpdate=true;delete m.userData.occlusionOriginal;fadedBuildingMeshes.delete(m);}
 }
}
function updatePresentation(dt) {
  updateDefenseRange();
  updateBuildingOcclusion(dt);
  for(let i=arrivalModels.length-1;i>=0;i--){
    const a=arrivalModels[i];a.age+=dt;
    const q=Math.min(1,a.age/.48),bounce=settings.motion?Math.sin(q*Math.PI*2)*Math.exp(-q*4)*.18:0;
    a.g.scale.set(a.scale.x*(1-bounce*.3),a.scale.y*(1+bounce),a.scale.z*(1-bounce*.3));
    if(q===1){a.g.scale.copy(a.scale);arrivalModels.splice(i,1);}
  }
  for(let i=impactRings.length-1;i>=0;i--){
    const a=impactRings[i];a.age+=dt;const q=a.age/.55;
    a.ring.scale.setScalar(settings.motion?.7+q*a.size:1.4);
    a.ring.material.opacity=Math.max(0,(1-q)*.42);
    if(q>=1){disposeObject(a.ring);impactRings.splice(i,1);}
  }
  updateWallConnections();
  const visiblePads=buildPads.filter(p=>padReady(p)&&!p.built&&!p.constructing&&(introStep>=4||(introStep===2&&p.index===12))).sort((a,b)=>distanceToDefense(a.type,a.x,a.z)-distanceToDefense(b.type,b.x,b.z)).slice(0,3);
  for(const p of buildPads)p.g.visible=visiblePads.includes(p)&&!(contextChoice?.index===p.index&&contextChoice.type!==p.type)&&phase==='day'&&!p.built&&!p.constructing&&Math.hypot(pPos.x-p.x,pPos.z-p.z)<9&&(introStep>=4||(introStep===2&&p.index===12));
  for(const [k,g] of wallDecorObjs){
    if(!g.userData.gates)continue;
    const [x,,z]=k.split(',').map(Number);
    const near=Math.hypot(pPos.x-x,pPos.z-z)<3;
    g.userData.open=(g.userData.open||0)+((near?1:0)-(g.userData.open||0))*Math.min(1,dt*12);
    g.userData.gates.forEach((leaf,i)=>leaf.rotation.y=(i===0?-1:1)*g.userData.open*1.5);
  }
}
function resetPresentation(){
  restoreBuildingOcclusion();
  for(const g of turretObjs.values())g.traverse(o=>{if(o.isMesh&&o.material.transparent){o.material.opacity=1;o.material.depthWrite=true;}});
  if(defenseRangeRing){defenseRangeRing.visible=false;defenseNextRing.visible=false;}
  if(wallConnectionMesh)wallConnectionMesh.count=0;
  impactRings.forEach(a=>disposeObject(a.ring));impactRings.length=0;
  arrivalModels.forEach(a=>a.g.scale.copy(a.scale));arrivalModels.length=0;
  guideLastStep=-1;guideCelebrateUntil=0;
}
function updateIntroGuide(){
  const el=$('introCard'),active=running&&introStep<4;
  el.hidden=!active;
  $('gameViewport').setAttribute('data-intro',active?'true':'false');
  if(!active)return;
  const step=introStep<2?0:introStep===2?1:2;
  if(guideLastStep!==step){
    if(guideLastStep>=0){guideCelebrateUntil=gameElapsed+1.2;sfx('complete');}
    guideLastStep=step;
  }
  const close=objectiveTarget&&Math.hypot(pPos.x-objectiveTarget.x,pPos.z-objectiveTarget.z)<1.4;
  const assembling=constructionSites.some(s=>s.p.type==='turret');
  const titles=['木に近づこう',assembling?'建築中':close?'建築ボタンをタップ':'矢塔の形へ','炉へ戻ろう'];
  const notes=['指を滑らせて移動',assembling?'少し離れると完成':close?'指を離す → タップ・木材40':'矢塔のそばへ移動','最初の夜を迎えよう'];
  $('introNumber').textContent=`${step+1} / 3`;
  $('introTitle').textContent=gameElapsed<guideCelebrateUntil?(step===1?'採集できた！':'矢塔が完成！'):titles[step];
  $('introHelp').textContent=notes[step];
  const hand=$('gestureGuide');hand.hidden=step===2||assembling;
  hand.setAttribute('data-release',close?'true':'false');
  if(objectiveTarget){
    const rect=renderer.domElement.getBoundingClientRect(),v=new THREE.Vector3(objectiveTarget.x,1.5,objectiveTarget.z).project(camera);
    hand.style.left=Math.max(50,Math.min(rect.width-50,(v.x*.5+.5)*rect.width+36))+'px';
    hand.style.top=Math.max(210,Math.min(rect.height-250,(-v.y*.5+.5)*rect.height+30))+'px';
  }
  if(step===1&&!assembling&&!$('quickDock').hidden){const r=$('quickAction').getBoundingClientRect();hand.hidden=false;hand.setAttribute('data-tap','true');hand.style.left=(r.left+18)+'px';hand.style.top=(r.top-12)+'px';}else hand.setAttribute('data-tap','false');
  if(assembling){const rect=renderer.domElement.getBoundingClientRect();hand.hidden=false;hand.setAttribute('data-release','false');hand.style.left=(rect.width-100)+'px';hand.style.top=(rect.height*.55)+'px';}
}


// ---- base ----
// base system — v12, integrated from the deployed v11.

function baseUpgradeCost() {
  return baseLevel === 1
    ? { wood: 70, coal: 20, iron: 0 }
    : baseLevel === 2
      ? { wood: 110, coal: 45, iron: 0 }
      : baseLevel === 3
        ? { wood: 150, coal: 65, iron: 20 }
        : baseLevel === 4
          ? { wood: 210, coal: 90, iron: 45 }
          : { wood: 999, coal: 999, iron: 999 };
}

function baseLevelName() {
  return baseLevel === 1
    ? "拠点"
    : baseLevel === 2
      ? "補強拠点"
      : baseLevel === 3
        ? "防衛集落"
        : baseLevel === 4
          ? "要塞拠点"
          : "極寒要塞";
}

let campCore=null;
function refreshBaseVisual() {
  fireGroup.position.set(-3.5,-.05,0);
  fireGroup.scale.setScalar(1.04);
  flamePts.position.set(-3.5,0,0);
  if(campGlow)campGlow.position.set(-3.5,.82,0);
  updateFurnaceEvolution();
  fireLight.distance=14+baseLevel*4;
}

function upgradeBase() {
  if (baseLevel >= 5) return false;
  const c = baseUpgradeCost();
  if (wood < c.wood || coal < c.coal || iron < c.iron) return false;
  wood -= c.wood;
  coal -= c.coal;
  iron -= c.iron;
  showResourceDelivery(c, 0, 0);
  baseLevel++;
  baseUpgradeProgress = 0;
  baseMax += 120;
  baseHP = baseMax;
  fuel = Math.min(100, fuel + 35);
  moveSpeed *= 1.04;
  playerDmg = Math.round(playerDmg * 1.08);
  if (baseLevel >= 2) {
    ensureWorkers();
    wood += 20;
  }
  if (baseLevel >= 3) {
    warehouseBonus += 25;
    coal += 15;
  }
  refreshBaseVisual();
  ensureFrontier();
  updateCampVisual();
  cargoBounce = 0.3;
  spawnVoxelBreakup(0, 1.8, 0, 0xffd36b, 20);
  updateHUD();
  sfx("base");
  showWaveBanner(
    "🏰 BASE Lv." + baseLevel,
    weaponCaption() + (baseLevel===3?" · 北の外周解放":baseLevel===4?" · 南の外周解放":""),
  );
  worldPop("拠点 Lv." + baseLevel, new THREE.Vector3(0, 3.2, 0), "#ffd98b");
  return true;
}

function updateBaseUpgrade(dt) {
  if (phase !== "day" || baseLevel >= 5) return;
  const d = Math.hypot(pPos.x, pPos.z);
  if (d > 2.8) {
    baseUpgradeProgress = 0;
    return;
  }
  const c = baseUpgradeCost();
  if (wood >= c.wood && coal >= c.coal && iron >= c.iron) {
    baseUpgradeProgress += dt;
    if (baseUpgradeProgress > 0.65) upgradeBase();
  } else baseUpgradeProgress = 0;
}

function makeSettlementModel(kind, level = baseLevel) {
  const g = new THREE.Group();
  if (kind === "tent") {
    const base = box(1.45, 0.56, 1.18, 0xb66e48);
    base.position.y = 0.82;
    g.add(base);
    addVoxelDetails(g, [
      [1.62, 0.18, 1.35, 0xe1b36b, 0, 1.18, 0],
      [1.2, 0.12, 1.48, 0xd89a56, 0, 1.31, 0],
      [0.18, 0.42, 0.06, 0x5d3c2c, 0, 0.76, 0.62],
      [0.24, 0.16, 0.06, 0xffc561, 0.35, 0.92, 0.63],
    ]);
  } else {
    const base = box(1.68, 0.94, 1.48, 0x956139);
    base.position.y = 1;
    g.add(base);
    addVoxelDetails(g, [
      [1.9, 0.22, 1.7, 0x665043, 0, 1.55, 0],
      [1.62, 0.18, 1.86, 0x554137, 0, 1.72, 0],
      [0.34, 0.42, 0.06, 0x553523, 0, 1.05, 0.78],
      [0.29, 0.3, 0.06, 0xffc968, 0.48, 1.12, 0.78],
      [0.29, 0.3, 0.06, 0xffc968, -0.48, 1.12, 0.78],
      [0.26, 0.52, 0.26, 0x705446, 0.62, 1.96, -0.38],
    ]);
  }
  g.scale.setScalar(level>=4?1.28:1.12);
  return g;
}
function addSettlementPiece(kind, x, z) {
  const g=makeSettlementModel(kind);
  g.position.set(x, 0, z);
  scene.add(g);
  settlementObjs.push(g);
}

function updateCampVisual(shownDay = day) {
  settlementObjs.forEach((g) => disposeObject(g));
  settlementObjs = [];
  if(survivalEnabled){
    const home=shownDay>=4||baseLevel>=3?"hut":"tent";
    if(shownDay>=2||baseLevel>=2){addSettlementPiece(home,-3.8,3.5);addSettlementPiece(home,3.8,3.5);}
    if(shownDay>=3||baseLevel>=3)addSettlementPiece("hut",-4.6,-4.5);
    if(shownDay>=4||baseLevel>=3)addSettlementPiece("hut",4.6,-4.5);
    addVillageServiceDetails();refreshBaseVisual();return;
  }
  if (shownDay >= 2 || baseLevel>=2) {
    addSettlementPiece("tent", -3.8, 3.5);
    addSettlementPiece("tent", 3.8, 3.5);
  }
  if (shownDay >= 3 || baseLevel>=3) addSettlementPiece("hut", -4.6, -4.1);
  if (shownDay >= 4 || baseLevel>=3) addSettlementPiece("hut", 4.6, -4.1);
  if (shownDay >= 5 || baseLevel>=4) {
    addSettlementPiece("tent", -5.5, .8);
    addSettlementPiece("tent", 5.5, .8);
  }
  if(baseLevel>=3)addSettlementPiece("hut",-10,-8);
  if(baseLevel>=4)addSettlementPiece("hut",10,8);
  refreshBaseVisual();
}

function clearCampExtras() {
  for (const o of [...buildPads, ...workerObjs, ...settlementObjs])
    if (o.g) disposeObject(o.g);
    else disposeObject(o);
  buildPads.forEach((p) => p.labelEl?.remove());
  buildPads = [];
  workerObjs = [];
  settlementObjs = [];
  wallDecorObjs.forEach((g) => disposeObject(g));
  wallDecorObjs.clear();
  turretObjs.forEach((g) => disposeObject(g));
  turretObjs.clear();
  flameObjs.forEach((g) => disposeObject(g));
  flameObjs.clear();
  warehouseObjs.forEach((g) => disposeObject(g));
  warehouseObjs.clear();
  defenseLabelEls.forEach((el) => el.remove());
  defenseLabelEls.clear();
  defenseState.clear();
}

function resetBaseVisual() {
  if(campCore){disposeObject(campCore);campCore=null;}
  for (const value of Object.values(fireGroup.userData))
    if (value?.isObject3D) disposeObject(value);
  fireGroup.userData = {};
  fireGroup.scale.setScalar(1);
}

function updateAutoFuel(dt, t) {
  fuelAutoCD -= dt;
  if (
    Math.hypot(pPos.x, pPos.z) < 2.2 &&
    fuel < 78 &&
    coal >= 10 &&
    fuelAutoCD <= 0
  ) {
    coal -= 10;
    fuel = Math.min(100, fuel + 30);
    fuelAutoCD = 1.2;
    showResourceDelivery({ coal: 10 }, 0, 0);
    burst(0, 1, 0, 0xffaa44, 12);
    toast("🔥 石炭を自動投入 +30%");
    updateHUD();
  }
}


// ---- outposts ----
// outposts system — v12, integrated from the deployed v11.

function outpostInfo(type) {
  return type === "sawmill"
    ? { name: "製材所", icon: "🪵", color: 0xffc66e, need: 2, prod: "🌲 +6" }
    : type === "coalmine"
      ? { name: "炭鉱", icon: "⛏️", color: 0xaec8ea, need: 2, prod: "🪨 +4" }
      : type === "ironmine"
        ? {
            name: "鉄鉱山",
            icon: "⚙️",
            color: 0xcfd8e2,
            need: 3,
            prod: "⚙️ +2",
          }
        : type === "survivor"
          ? {
              name: "生存者キャンプ",
              icon: "🧑",
              color: 0x9de3a0,
              need: 2,
              prod: "住民 +1",
            }
          : {
              name: "研究所跡地",
              icon: "🔬",
              color: 0x9ed7ff,
              need: 4,
              prod: "全塔 +10%",
            };
}

