function initOutposts() {
  outposts.forEach((o) => {
    disposeObject(o.g);
  });
  outposts = [];
  stageConfig().outposts.forEach(([type, x, z]) => {
    const i = outpostInfo(type),
      g = makeOutpostVisual(type, x, z),
      tag = makeGroundTag(
        i.icon + " " + i.name,
        "🔒 拠点Lv." + i.need,
        "#8ea6bd",
        3.25,
        0.88,
      );
    tag.position.set(x, 0.56, z);
    tag.userData.radius = 2.4;
    outposts.push({
      type,
      x,
      z,
      g,
      tag,
      captured: false,
      hp: 240,
      maxHp: 240,
      progress: 0,
      prodT: 0,
    });
  });
}

function refreshOutpostTag(o) {
  if(expedition.pilot&&o.type!=='ironmine'&&!(journey&&o.type==='coalmine')){const facility=o.type==='sawmill';setGroundTag(o.tag,facility?'古い製材所':'技師の避難所',facility?(expedition.facility==='invested'?'毎朝 木材36':expedition.facility==='salvaged'?'解体済み':'修復 / 解体を選ぶ'):(expedition.engineer?'救出済み':'木材35で救出'),'#ffd38a');return;}
  const i = outpostInfo(o.type);
  if (o.captured)
    setGroundTag(
      o.tag,
      i.icon + " " + i.name + " ✓",
      i.prod + " / HP " + Math.max(0, o.hp | 0),
      "#86f0b1",
    );
  else if (baseLevel < i.need)
    setGroundTag(
      o.tag,
      i.icon + " " + i.name,
      "🔒 拠点Lv." + i.need,
      "#8ea6bd",
    );
  else
    setGroundTag(o.tag, i.icon + " " + i.name, "確保 / " + i.prod, "#ffd36b");
}

function updateOutposts(dt) {
  for (const o of outposts) {
    if(expedition.pilot&&o.type!=="ironmine"&&!(journey&&o.type==='coalmine'))continue;
    refreshOutpostTag(o);
    if (phase !== "day" && campPlan !== "supply") continue;
    const d = Math.hypot(o.x - pPos.x, o.z - pPos.z);
    if (
      !expedition.pilot && phase === "day" && !o.captured &&
      baseLevel >= outpostInfo(o.type).need &&
      d < 2.4 &&
      !movementRequested()
    ) {
      o.progress += dt;
      if (o.progress > 0.7) {
        o.progress = 0;
        o.captured = true;
        o.everCaptured = true;
        outpostNotice = {type:o.type,until:gameElapsed+8};
        o.hp = o.maxHp;
        sfx("capture");
        showWaveBanner("拠点を確保", outpostInfo(o.type).name + " を確保");
        if (!o.rewardClaimed && o.type === "survivor") {
          rescued++;
          makeWorker(workerObjs.length);
        }
        if (!o.rewardClaimed && o.type === "research") {
          turretDmg = Math.round(turretDmg * 1.1);
          playerDmg = Math.round(playerDmg * 1.08);
        }
        o.rewardClaimed = true;
      }
    } else if (!o.captured) o.progress = 0;
    if (o.captured) {
      o.prodT -= dt;
      if (o.prodT <= 0) {
        o.prodT = 4.2;
        if (o.type === "sawmill") {
          wood += 6;
          sfx("wood");
        } else if (o.type === "coalmine") {
          coal += 4;
          sfx("coal");
        } else if (o.type === "ironmine") {
          iron += 2;
        if(expedition.pilot){spawnPickupTrail(o.x,1.8,o.z,0xb9e7ef,2,player.position.clone(),2);worldPop("鉄 +2",o.g.position.clone().add(new THREE.Vector3(0,2,0)),"#bdeaff");}
          sfx("iron");
        }
        updateHUD();
      }
    }
  }
}

function activeOutposts() {
  // The expedition rules use logistics sites, not a second combat front. Legacy campaigns retain it.
  if(expedition.pilot)return journey?outposts.filter(o=>o.type==='coalmine'&&o.captured&&o.hp>0):[];
  return outposts.filter((o) => o.captured && o.hp > 0);
}

function damageOutpost(o, dmg) {
  o.hp -= dmg;
  if (o.hp <= 0) {
    o.hp = 0;
    o.captured = false;
    o.everCaptured = true;
    outpostNotice = {type:o.type,until:gameElapsed+14};
    if(trackedOutpost===o.type) trackedOutpost=null;
    o.progress = 0;
    showWaveBanner("拠点が陥落", outpostInfo(o.type).name + " が陥落");
  }
}

function chooseNightModifier() {
  const pool =
    day <= 2 ? ["normal", "wolf"] : ["wolf", "fuel", "armored", "siege"];
  if (day === 6) pool.push("bossOmen");
  nightModifier = pool[Math.floor(Math.random() * pool.length)];
  const map = {
    normal: ["静かな夜", "通常襲撃"],
    wolf: ["狼の夜", "高速の狼が大量出現"],
    fuel: ["燃料危機", "燃料消費 +70%"],
    armored: ["重装襲来", "高耐久兵が増加"],
    siege: ["破城の夜", "防壁狙いが増加"],
    bossOmen: ["巨大な足跡", "次夜にボス襲来"],
  };
  return map[nightModifier];
}


// ---- buildings ----
function defenseUpgradeLimit(){return Math.min(MAX_DEF_LV,survivalEnabled?baseLevel:baseLevel+1);}
// buildings system — v12, integrated from the deployed v11.

function isGateWall(x,z){return x===0 || (Math.abs(x)>=8 && z===-3);}
function typeName(t,x,z) {
  return t === "wall"
    ? (isGateWall(x,z)?"通用門":"防壁")
    : t === "turret"
      ? "矢塔"
      : t === "flame"
        ? "火炎塔"
        : "補給所";
}

function typeIcon(t) {
  return t === "wall"
    ? "🧱"
    : t === "turret"
      ? "🏹"
      : t === "flame"
        ? "🔥"
        : "📦";
}

function requiredBaseLevel(type) {
  return type === "wall" || type === "turret" ? 1 : 2;
}

function buildPadDefinitions(layout = survivalEnabled ? 2 : 0) {
  const defs = [];
  for (const x of [-5, 0, 5])
    for (const z of [-6, 6]) defs.push([x, z, "wall", 15]);
  for (const z of [-3, 3])
    for (const x of [-8, 8]) defs.push([x, z, "wall", 15]);
  defs.push(
    [-8, -8, "turret", 40],
    [8, -8, "turret", 40],
    [-8, 8, "turret", 40],
    [8, 8, "turret", 40],
  );
  defs.push(
    [0, -10, "flame", 55],
    [0, 10, "flame", 55],
    [-10, 0, "warehouse", 45],
    [10, 0, "warehouse", 45],
  );
  for(const x of [-10,-5,0,5,10])for(const z of [-14,14])defs.push([x,z,"wall",15]);
  for(const x of [-14,14])for(const z of [-9,-3,3,9])defs.push([x,z,"wall",15]);
  if(layout===2){for(let i=10;i<14;i++){defs[i][0]=Math.sign(defs[i][0])*10;defs[i][1]=Math.sign(defs[i][1])*10;}defs[14][0]=-4;defs[14][1]=-11;defs[15][0]=4;defs[15][1]=11;}
  return defs;
}
function isReservedBuildArea(x, z) {
  return travelLane(x,z)||buildPadDefinitions().some(
    ([bx, bz, type]) => distanceToDefense(type, bx, bz, x, z) < 1,
  );
}
function addBuildPads() {
  buildPadDefinitions().forEach(([x, z, type, cost], index) => {
    // One footprint outline, at the actual building location. No second disc or offset marker.
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    const ghost=makeBuildSilhouette(type,x,z);g.add(ghost);
    scene.add(g);
    const tag = makeGroundTag(typeIcon(type), "");
    tag.position.set(x, 0.56, z);
    setTagFootprint(tag, type, x, z);
    tag.userData.pad = true;
    buildPads.push({
      g,
      x,
      z,
      type,
      cost:type==='wall'?cost:EQUIPMENT[type].wood,
      built: false,
      progress: 0,
      index,
      tag,
    });
  });
}

function getDefenseMaxHp(type, level) {
  const base = type === "wall" ? WALL_HP : type === "warehouse" ? 150 : 110;
  return Math.round(base * (1 + (level - 1) * 0.65));
}

function getUpgradeCost(state) {
  if(state.level>=MAX_DEF_LV)return {wood:Infinity,coal:Infinity};
  if(state.level>=3)return {wood:state.type==='wall'?40+(state.level-3)*20:65+(state.level-3)*25,coal:state.type==='wall'?12+(state.level-3)*8:25+(state.level-3)*10};
  if (state.type === "wall")
    return state.level === 1
      ? { wood: 24, coal: 0 }
      : state.level === 2
        ? { wood: 44, coal: 10 }
        : { wood: 999, coal: 999 };
  if (state.type === "turret")
    return state.level === 1
      ? { wood: 34, coal: 14 }
      : state.level === 2
        ? { wood: 56, coal: 26 }
        : { wood: 999, coal: 999 };
  if (state.type === "flame")
    return state.level === 1
      ? { wood: 30, coal: 8 }
      : state.level === 2
        ? { wood: 45, coal: 20 }
        : { wood: 999, coal: 999 };
  return state.level === 1
    ? { wood: 24, coal: 6 }
    : state.level === 2
      ? { wood: 36, coal: 16 }
      : { wood: 999, coal: 999 };
}

function addWallDecor(x, y, z, level = 1) {
  const k = key(x, y, z);
  if (wallDecorObjs.has(k)) {
    disposeObject(wallDecorObjs.get(k));
    wallDecorObjs.delete(k);
  }
    const g = makeWallModel(x,z,level);
    evolveDefenseModel(g,'wall',level);
    g.position.set(x,y-.5,z);scene.add(g);wallDecorObjs.set(k,g);
}
function makeWallModel(x,z,level=1) {
    const g = new THREE.Group();
  // Local X follows the wall. Two hinged doors form a readable, player-only passage.
  if(Math.abs(x)>=Math.abs(z))g.rotation.y=Math.PI/2;
  if(!isGateWall(x,z)){
    for(let i=-4;i<=4;i++){const post=box(.32,1.65,.38,0x866d51);post.position.set(i*.44,.85,0);g.add(post);const snow=box(.36,.15,.45,0xe0ece7);snow.position.set(i*.44,1.75,0);g.add(snow);}
    for(const height of [.55,1.2]){const rail=box(4,.15,.48,0x375864);rail.position.y=height;g.add(rail);}
      return g;
  }
  for(const side of [-1,1]){
    const post=box(.36,2.05,.5,0x42636a);post.position.set(side*1.5,1,0);g.add(post);
    const cap=box(.52,.2,.65,0xe3efe9);cap.position.set(side*1.5,2.08,0);g.add(cap);
    const wing=box(.66,1.35,.35,0x927050);wing.position.set(side*1.65,.75,0);g.add(wing);
    const leaf=new THREE.Group();leaf.position.set(side*1.3,0,0);
    const panel=box(1.28,1.45,.18,level>=3?0xbb9760:0x94724d);
    panel.position.set(-side*.64,.82,0);leaf.add(panel);
    const brace=box(1.18,.15,.24,0xe2b96b);brace.position.set(-side*.64,.88,0);leaf.add(brace);
    g.add(leaf);(g.userData.gates ||= []).push(leaf);
  }
  const arch=box(3.4,.28,.58,0x395964);arch.position.y=2.26;g.add(arch);
  const light=box(.42,.34,.15,0xffcd79);light.position.set(0,2.3,.36);g.add(light);
    return g;
}

