function refreshDefenseVisual(x, y, z) {
  const st = defenseState.get(key(x, y, z));
  if (!st) return;
  if (st.type === "turret") addTurretVisual(x, y, z, st.level);
  else if (st.type === "flame") addFlameVisual(x, y, z, st.level);
  else if (st.type === "warehouse") addWarehouseVisual(x, y, z, st.level);
  else addWallDecor(x, y, z, st.level);
}

function findUpgradeableDefenseNear() {
  let best = null,
    bd = 0.7;
  defenseState.forEach((st, k) => {
    if (st.level >= MAX_DEF_LV) return;
    const [x, y, z] = k.split(",").map(Number),
      d = distanceToDefense(st.type, x, z);
    if (d < bd) {
      bd = d;
      best = { x, y, z, state: st };
    }
  });
  return best;
}

function upgradeDefense(hit) {
  const st = hit.state,
    cost = getUpgradeCost(st);
  if (st.level>=defenseUpgradeLimit()||!canAfford(cost)) return false;
  wood -= cost.wood;
  coal -= cost.coal;
  if(st.type!=='wall'){st.investment ||= equipmentValue(st.type,st.level);st.investment.wood+=cost.wood;st.investment.coal+=cost.coal;}
  st.level++;
  st.maxHp = getDefenseMaxHp(st.type, st.level);
  st.hp = st.maxHp;
  if (st.type === "warehouse") warehouseBonus += 25;
  const b = blockAt(hit.x, hit.y, hit.z);
  if (b) b.hp = st.maxHp;
  refreshDefenseVisual(hit.x, hit.y, hit.z);
  showResourceDelivery(cost, hit.x, hit.z);
  burst(hit.x, 1.2, hit.z, st.type === "turret" ? 0x8ed1ff : 0xffd27a, 18);
  worldPop(
    typeName(st.type,hit.x,hit.z) + " Lv." + st.level,
    new THREE.Vector3(hit.x, 2.3, hit.z),
    "#ffe19a",
  );
  sfx("upgrade");
  toast(
    typeIcon(st.type) +
      " " +
      typeName(st.type,hit.x,hit.z) +
      " をLv." +
      st.level +
      "に進化",
  );
  updateHUD();
  return true;
}

function updateDefenseUpgrades(dt) {
  const hit =
    phase === "day" &&
    !movementRequested() &&
    !defenseActionConsumed &&
    !nearestBuildPad()
      ? findUpgradeableDefenseNear()
      : null;
  for (const st of defenseState.values())
    if (st !== hit?.state) st._progress = 0;
  if (!hit) return;
  const st = hit.state,
    cost = getUpgradeCost(st);
  if (wood >= cost.wood && coal >= cost.coal) {
    st._progress = (st._progress || 0) + dt;
    if (st._progress >= 0.8) {
      st._progress = 0;
      if (upgradeDefense(hit)) defenseActionConsumed = true;
    }
  } else {
    st._progress = 0;
    if (Math.random() < dt * 0.6)
      toast(
        (st.type === "turret" ? "🏹" : "🧱") +
          " 進化に 木材" +
          cost.wood +
          " / 石炭" +
          cost.coal +
          " が必要",
      );
  }
}

function getBuildCost(p) {
  if (p.type !== "wall") return { wood: EQUIPMENT[p.type].wood, coal: EQUIPMENT[p.type].coal };
  return { wood: p.cost, coal: 0 };
}

function turretRange(level) { return T_RANGE + (level - 1) * 2.1; }
function updateDefenseCombat(dt, t) {
  for (const [k, g] of turretObjs) {
    const [tx, ty, tz] = k.split(",").map(Number),
      st = defenseState.get(k),
      lv = st ? st.level : 1,
      profile=towerCombatProfile(st),
      range = profile.range,
      rate = profile.rate,
      dmg = Math.round(turretDmg * (1 + (lv - 1) * 0.55)*profile.damage);
    g._cd = (g._cd || 0) - dt;
    if (g._cd > 0) continue;
    let best = null,
      bd = 1e9;
    for (const e of enemies) {
      if (!enemyTargetable(e)) continue;
      const d = g.position.distanceTo(e.model.g.position);
      const score = defenseTargetScore(e,d)+(st?.specialization==='sniper'&&e.kind==='thrower'?-1000:0)+(st?.specialization==='pierce'&&e.kind==='armored'?-500:0);
      if (d < range && d>=profile.minRange && score < bd) {
        bd = score;
        best = e;
      }
    }
    if (best) {
      g._cd = rate * Math.max(coldAttackInterval(),(st?.frost || 0)>0 ? 2.8 : 1);
      const from = new THREE.Vector3(tx, ty + 2.1, tz),
        dir = enemyAimPoint(best).sub(from).normalize();
      shootArrow(from, dir, dmg, best);arrows.at(-1).tactic=st?.specialization||null;
      sfx("shoot");
    }
  }
  for (const [k, g] of flameObjs) {
    const st = defenseState.get(k);
    if (!st) continue;
    const [x, y, z] = k.split(",").map(Number),
      lv = st.level;
    g._cd = (g._cd || 0) - dt;
    if (g._cd > 0) continue;
    const range = 5.3 + lv * 0.65,
      targets = enemies.filter(
        (e) =>
          enemyTargetable(e) && (e.kind!=="boss" || e.legacyMotion || e.maneuver==='recover') &&
          Math.hypot(e.model.g.position.x - x, e.model.g.position.z - z) <
            range,
      );
    if (targets.length) {
      sfx("flame");
      g._cd = Math.max(0.45, 1.15 - lv * 0.18) * Math.max(coldAttackInterval(),(st.frost||0)>0?2.8:1);
      for (const e of targets.slice(0, 3 + lv)) {
        damageEnemy(e, (10 + lv * 9) * (e.kind==='armored' ? .45 : 1),'flame');
        if(e.kind!=="boss")e.slowUntil=gameElapsed+1.4;
        const aim = enemyAimPoint(e);
        burst(aim.x, aim.y, aim.z, 0xff6b38, 4);
      }
      burst(x, 1.5, z, 0xff8a42, 10);
    }
  }
}

// Empty sites show the thing that can be built, at its actual footprint.
