function solidAt(x, z) {
  for (const [k, st] of defenseState) {
    const [bx, by, bz] = k.split(",").map(Number),
      f = defenseFootprint(st.type, bx, bz);
    if (Math.abs(x - bx) <= f.width / 2 && Math.abs(z - bz) <= f.depth / 2)
      return blockAt(bx, by, bz);
  }
  const link=wallConnectorAt(x,z);
  return link?blocks.get(link.k):null;
}

function nearestFreePosition(x, z) {
  if (!playerCollidesAt(x, z)) return { x, z };
  for (let radius = 0.35; radius <= 3.5; radius += 0.25) {
    const steps = Math.max(12, Math.ceil(radius * 18));
    for (let i = 0; i < steps; i++) {
      const a = (i / steps) * Math.PI * 2,
        nx = x + Math.cos(a) * radius,
        nz = z + Math.sin(a) * radius;
      if (Math.max(Math.abs(nx), Math.abs(nz)) > R_INNER - 0.45) continue;
      if (!playerCollidesAt(nx, nz)) return { x: nx, z: nz };
    }
  }
  return { x: 0, z: 4 };
}

function movePlayerWithCollision(dx, dz) {
  const lim = R_INNER - 0.45,
    sx = pPos.x,
    sz = pPos.z,
    tx = Math.max(-lim, Math.min(lim, sx + dx)),
    tz = Math.max(-lim, Math.min(lim, sz + dz));
  if (!playerCollidesAt(tx, tz)) {
    pPos.x = tx;
    pPos.z = tz;
    return;
  }
  if (!playerCollidesAt(tx, sz)) {
    pPos.x = tx;
    return;
  }
  if (!playerCollidesAt(sx, tz)) {
    pPos.z = tz;
    return;
  }
  if (playerCollidesAt(pPos.x, pPos.z)) {
    const safe = nearestFreePosition(pPos.x, pPos.z);
    pPos.x = safe.x;
    pPos.z = safe.z;
  }
}

function resolvePlayerCollision() {
  if (playerCollidesAt(pPos.x, pPos.z)) {
    const safe = nearestFreePosition(pPos.x, pPos.z);
    pPos.x = safe.x;
    pPos.z = safe.z;
  }
}

function updatePlayer(dt, t) {
  let mx =
      (keys.KeyD || keys.ArrowRight ? 1 : 0) -
      (keys.KeyA || keys.ArrowLeft ? 1 : 0) +
      joyVec.x,
    mz =
      (keys.KeyW || keys.ArrowUp ? 1 : 0) -
      (keys.KeyS || keys.ArrowDown ? 1 : 0) +
      joyVec.y,
    ml = Math.hypot(mx, mz);
  if (ml > 1) {
    mx /= ml;
    mz /= ml;
  }
  const right = new THREE.Vector3(
      1,
      0,
      -CAM_OFFSET.x / CAM_OFFSET.z,
    ).normalize(),
    forward = new THREE.Vector3(-CAM_OFFSET.x, 0, -CAM_OFFSET.z).normalize(),
    wx = (right.x * mx + forward.x * mz) * moveSpeed,
    wz = (right.z * mx + forward.z * mz) * moveSpeed;
  movePlayerWithCollision(wx * dt, wz * dt);
  resolvePlayerCollision();
  player.position.copy(pPos);
  gatherRing.position.set(pPos.x, 0.56, pPos.z);
  attackRing.position.set(pPos.x, 0.56, pPos.z);
  attackRing.material.opacity = phase === "night" ? 0.18 : 0.08;
  attackRing.visible = false;
  gatherRing.visible=blockArr.some(b=>["wood","leaf","coal","iron"].includes(b.b.t)&&Math.hypot(b.x-pPos.x,b.z-pPos.z)<1.8);
  shootPose = Math.max(0, shootPose - dt);
  rifle.visible = !survivalEnabled && phase === "night" && baseLevel>=4;
  muzzle.visible = shootPose > 0.11;
  rifle.position.z = 0.35 - (shootPose / 0.2) * 0.12;
  if (ml > 0.08 && shootPose <= 0) player.rotation.y = Math.atan2(wx, wz);
  const moving = ml > 0.15,
    sw = moving ? Math.sin(t * 11) * 0.7 : 0;
  limbs.legL.rotation.x = sw;
  limbs.legR.rotation.x = -sw;
  limbs.armL.rotation.x = -sw * 0.8;
  limbs.armR.rotation.x = sw * 0.8;
  if (shootCD > 0) shootCD -= dt;
  if (comboT > 0) {
    comboT -= dt;
    if (comboT <= 0) {
      combo = 0;
      $("combo").style.opacity = 0;
    }
  }
  camLook.lerp(
    cameraFocusPoint(),
    Math.min(1, dt * 7),
  );
  camera.position.lerp(camLook.clone().add(CAM_OFFSET), Math.min(1, dt * 6));
  if (shake > 0 && settings.motion) {
    camera.position.x += (Math.random() - 0.5) * shake * 0.07;
    camera.position.y += (Math.random() - 0.5) * shake * 0.05;
    shake -= dt * 3;
  }
  camera.lookAt(camLook.x, camLook.y + 0.1, camLook.z);
  if (phase === "night" && shootCD <= 0 && enemies.length) {
    let target = null,
      bd = Infinity;
    for (const e of enemies) {
      if (!enemyTargetable(e)) continue;
      const d = e.model.g.position.distanceTo(player.position);
      const score=e.kind==='boss'&&!e.legacyMotion&&dragonExposed(e)?d-200:d;
      if (d < playerWeapon().range && score < bd) {
        bd = score;
        target = e;
      }
    }
    if (target) {
      const weapon=playerWeapon();shootCD=weapon.interval;
      if(weapon.kind==='melee'){sweepVillageAxe(target);return;}
      const aim = enemyAimPoint(target);
      player.rotation.y = Math.atan2(aim.x - pPos.x, aim.z - pPos.z);
      player.updateMatrixWorld(true);
      const from = (baseLevel>=4?muzzle:harvestTool).getWorldPosition(new THREE.Vector3()),
        dir = aim.sub(from).normalize();
      shootPose = 0.2;
      muzzle.visible = baseLevel>=4;
      if(weapon.kind==='axe')harvestSwing=.24;
      const targets=target.kind==='boss'&&!target.legacyMotion&&dragonExposed(target)?[target]:enemies.filter(enemyTargetable).filter(e=>e.model.g.position.distanceTo(player.position)<weapon.range).sort((a,b)=>a.model.g.position.distanceTo(player.position)-b.model.g.position.distanceTo(player.position));
      for(let i=0;i<weapon.count;i++){const e=targets[i%targets.length]||target;const origin=from.clone();if(weapon.kind==='bullet')origin.add(new THREE.Vector3(i===0?-.09:.09,0,0).applyQuaternion(player.quaternion));shootArrow(origin,enemyAimPoint(e).sub(origin).normalize(),playerDmg,e,weapon.kind);const a=arrows.at(-1);if(weapon.kind==='axe')a.v.multiplyScalar(.6);}

      sfx(weapon.kind==='axe'?'axeSwing':'gunShot');
    }
  }
  if (shootPose > 0) {
    limbs.armR.rotation.x = -1.25;
    limbs.armL.rotation.x = -0.95;
  }
}

function cameraFocusPoint(){
  const focus=new THREE.Vector3(pPos.x,pPos.y+1,pPos.z);
  if(introStep===3){focus.x-=.55;}
  else if(introStep<3 && objectiveTarget){
    const dx=objectiveTarget.x-pPos.x,dz=objectiveTarget.z-pPos.z;
    const w=Math.min(.32,2/Math.max(1,Math.hypot(dx,dz)));
    focus.x+=dx*w;focus.z+=dz*w;
  }else if(Math.hypot(pPos.x,pPos.z)<13){focus.x*=.84;focus.z*=.84;}
  return focus;
}


