    if(p.type!=="wall")continue;
    if ((!inspectAll&&phase === "night" && !inNightRespite()) || p.built || p.constructing || (!inspectAll&&(!padUnlocked(p) || baseLevel < requiredBaseLevel(p.type))))
      continue;
