function nearbyResource(type) {
  let target=null, distance=Infinity;
  for(const e of blockArr){
    if(e.y!==1 || e.b.t!==type)continue;
    const d=Math.hypot(e.x-pPos.x,e.z-pPos.z);
    if(d<distance){target={x:e.x,z:e.z};distance=d;}
  }
  return target;
}
