  $("outpostDetail").textContent=lost?"生産停止 / 昼に戻れば再確保できる":o.captured?`耐久 ${Math.ceil(o.hp/240*100)}% · ${postYield(o)}${["sawmill","coalmine","ironmine"].includes(o.type)?campPlan==="supply"?" / 4.2秒・夜も生産":" / 4.2秒・昼のみ":""}`:`${postYield(o)} / 遠くの拠点にも敵が来る`;
